PRAGMA foreign_keys=ON;
CREATE TABLE lab_meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE body(body_id TEXT PRIMARY KEY,canonical_name TEXT NOT NULL UNIQUE,body_class TEXT NOT NULL,parent_body_id TEXT REFERENCES body(body_id),status TEXT NOT NULL DEFAULT 'EXPERIMENTAL');
CREATE TABLE body_identifier(body_id TEXT NOT NULL REFERENCES body(body_id),authority TEXT NOT NULL,identifier_type TEXT NOT NULL,identifier_value TEXT NOT NULL,status TEXT NOT NULL,PRIMARY KEY(body_id,authority,identifier_type,identifier_value),UNIQUE(authority,identifier_type,identifier_value));
CREATE TABLE source(source_id INTEGER PRIMARY KEY,source_key TEXT NOT NULL UNIQUE,title TEXT NOT NULL,authority TEXT,source_type TEXT NOT NULL,url TEXT,doi TEXT,publication_date TEXT,acquired_at TEXT,notes TEXT);
CREATE TABLE source_artifact(artifact_id INTEGER PRIMARY KEY,source_id INTEGER NOT NULL REFERENCES source(source_id),artifact_key TEXT NOT NULL UNIQUE,local_path TEXT,sha256 TEXT,byte_count INTEGER,retrieval_url TEXT,acquired_at TEXT,origin_kind TEXT NOT NULL CHECK(origin_kind IN('LOOM_FROZEN','LAB_ACQUIRED','REMOTE_REFERENCE_ONLY')),CHECK(sha256 IS NULL OR length(sha256)=64));
CREATE TABLE ephemeris_source(ephemeris_source_id INTEGER PRIMARY KEY,provider TEXT NOT NULL,product_name TEXT NOT NULL,product_version TEXT,asset_filename TEXT,sha256 TEXT,byte_count INTEGER,source_url TEXT,acquired_at TEXT,status TEXT NOT NULL);
CREATE TABLE ephemeris_coverage(ephemeris_source_id INTEGER NOT NULL REFERENCES ephemeris_source(ephemeris_source_id),body_id TEXT REFERENCES body(body_id),valid_from TEXT,valid_until TEXT,reference_frame TEXT NOT NULL,units TEXT NOT NULL,coverage_class TEXT NOT NULL,status TEXT NOT NULL,PRIMARY KEY(ephemeris_source_id,body_id,reference_frame));
CREATE TABLE region(region_id INTEGER PRIMARY KEY,body_id TEXT NOT NULL REFERENCES body(body_id),region_key TEXT NOT NULL,region_name TEXT NOT NULL,region_type TEXT NOT NULL,parent_region_id INTEGER REFERENCES region(region_id),geometry_ref TEXT,notes TEXT,UNIQUE(body_id,region_key));
CREATE TABLE spatial_product(spatial_product_id INTEGER PRIMARY KEY,body_id TEXT NOT NULL REFERENCES body(body_id),region_id INTEGER REFERENCES region(region_id),product_key TEXT NOT NULL UNIQUE,product_type TEXT NOT NULL,title TEXT NOT NULL,source_id INTEGER NOT NULL REFERENCES source(source_id),horizontal_resolution_value REAL,horizontal_resolution_unit TEXT,vertical_sensitivity_min REAL,vertical_sensitivity_max REAL,vertical_sensitivity_unit TEXT,vertical_coordinate_type TEXT CHECK(vertical_coordinate_type IN('ALTITUDE','DEPTH_BELOW_SURFACE','PRESSURE_LEVEL','NONE') OR vertical_coordinate_type IS NULL),vertical_min REAL,vertical_max REAL,vertical_unit TEXT,vertical_datum TEXT,geometry_ref TEXT,coordinate_frame TEXT,scope TEXT NOT NULL CHECK(scope IN('BODY','REGION','FOOTPRINT','LOCAL_SITE','SAMPLE','MODEL_DOMAIN')),status TEXT NOT NULL CHECK(status IN('CANDIDATE','ADMITTED','RETIRED')));
CREATE TABLE observation(observation_id INTEGER PRIMARY KEY,body_id TEXT NOT NULL REFERENCES body(body_id),region_id INTEGER REFERENCES region(region_id),spatial_product_id INTEGER REFERENCES spatial_product(spatial_product_id),observation_key TEXT NOT NULL UNIQUE,measurement_method TEXT,scope TEXT NOT NULL CHECK(scope IN('BODY','REGION','FOOTPRINT','LOCAL_SITE','SAMPLE','MODEL_DOMAIN')),observation_time TEXT,observation_time_start TEXT,observation_time_end TEXT,horizontal_resolution_value REAL,horizontal_resolution_unit TEXT,vertical_sensitivity_min REAL,vertical_sensitivity_max REAL,vertical_sensitivity_unit TEXT,vertical_coordinate_type TEXT CHECK(vertical_coordinate_type IN('ALTITUDE','DEPTH_BELOW_SURFACE','PRESSURE_LEVEL','NONE') OR vertical_coordinate_type IS NULL),vertical_min REAL,vertical_max REAL,vertical_unit TEXT,vertical_datum TEXT,source_id INTEGER NOT NULL REFERENCES source(source_id),notes TEXT);
CREATE TABLE sample(sample_id INTEGER PRIMARY KEY,body_id TEXT NOT NULL REFERENCES body(body_id),region_id INTEGER REFERENCES region(region_id),sample_key TEXT NOT NULL UNIQUE,sample_name TEXT NOT NULL,collection_site TEXT,collection_method TEXT,collection_time_start TEXT,collection_time_end TEXT,mass_value REAL,mass_unit TEXT,source_id INTEGER NOT NULL REFERENCES source(source_id),notes TEXT);
CREATE TABLE scientific_assertion(assertion_id INTEGER PRIMARY KEY,assertion_key TEXT NOT NULL UNIQUE,body_id TEXT NOT NULL REFERENCES body(body_id),property_code TEXT NOT NULL,ontology TEXT NOT NULL CHECK(ontology IN('REAL_EVIDENCE','MODEL_INFERENCE','DERIVED','REALIZED_OBSERVATION')),scope TEXT NOT NULL CHECK(scope IN('BODY','REGION','FOOTPRINT','LOCAL_SITE','SAMPLE','MODEL_DOMAIN')),region_id INTEGER REFERENCES region(region_id),observation_id INTEGER REFERENCES observation(observation_id),sample_id INTEGER REFERENCES sample(sample_id),spatial_product_id INTEGER REFERENCES spatial_product(spatial_product_id),value_kind TEXT NOT NULL CHECK(value_kind IN('NUMERIC','VECTOR','TEXT','CATEGORY','DETECTION','BOUND','RANGE','MODEL','SPATIAL_PRODUCT','UNKNOWN')),value_numeric REAL,value_text TEXT,unit TEXT,uncertainty_numeric REAL,uncertainty_text TEXT,value_min REAL,value_max REAL,bound_operator TEXT,vertical_coordinate_type TEXT CHECK(vertical_coordinate_type IN('ALTITUDE','DEPTH_BELOW_SURFACE','PRESSURE_LEVEL','NONE') OR vertical_coordinate_type IS NULL),vertical_min REAL,vertical_max REAL,vertical_unit TEXT,vertical_datum TEXT,epistemic_class TEXT NOT NULL,measurement_method TEXT,representativeness TEXT NOT NULL CHECK(representativeness IN('BODY_REPRESENTATIVE','REGION_REPRESENTATIVE','SITE_ONLY','SAMPLE_ONLY','FOOTPRINT_ONLY','MODEL_DOMAIN_ONLY','UNKNOWN')),confidence TEXT,knowledge_date TEXT,valid_time_start TEXT,valid_time_end TEXT,source_id INTEGER NOT NULL REFERENCES source(source_id),source_artifact_id INTEGER REFERENCES source_artifact(artifact_id),source_locator TEXT,lineage TEXT,admission_status TEXT NOT NULL CHECK(admission_status IN('CANDIDATE','ADMITTED','HOLD','RETIRED')),preferred INTEGER NOT NULL DEFAULT 0 CHECK(preferred IN(0,1)),origin TEXT NOT NULL CHECK(origin IN('EXISTING_LOOM','NEW_CHATGPT_RESEARCH','TEST_FIXTURE_ONLY')),notes TEXT,CHECK(value_kind='UNKNOWN' OR value_numeric IS NOT NULL OR value_text IS NOT NULL OR value_min IS NOT NULL OR value_max IS NOT NULL OR spatial_product_id IS NOT NULL),CHECK(scope IN('BODY','MODEL_DOMAIN') OR region_id IS NOT NULL OR observation_id IS NOT NULL OR sample_id IS NOT NULL OR spatial_product_id IS NOT NULL));
CREATE INDEX idx_assertion_query ON scientific_assertion(body_id,property_code,ontology,scope,admission_status);
CREATE TABLE assertion_input(assertion_id INTEGER NOT NULL REFERENCES scientific_assertion(assertion_id) ON DELETE CASCADE,input_assertion_id INTEGER REFERENCES scientific_assertion(assertion_id),input_observation_id INTEGER REFERENCES observation(observation_id),input_spatial_product_id INTEGER REFERENCES spatial_product(spatial_product_id),role TEXT NOT NULL,CHECK((input_assertion_id IS NOT NULL)+(input_observation_id IS NOT NULL)+(input_spatial_product_id IS NOT NULL)=1));
CREATE TABLE material_evidence(material_evidence_id INTEGER PRIMARY KEY,body_id TEXT NOT NULL REFERENCES body(body_id),region_id INTEGER REFERENCES region(region_id),observation_id INTEGER REFERENCES observation(observation_id),sample_id INTEGER REFERENCES sample(sample_id),material_family TEXT NOT NULL,material_species TEXT,phase TEXT,physical_form TEXT,evidence_class TEXT NOT NULL,abundance_semantics TEXT NOT NULL,abundance_value REAL,abundance_min REAL,abundance_max REAL,abundance_unit TEXT,depth_min REAL,depth_max REAL,depth_unit TEXT,scope TEXT NOT NULL CHECK(scope IN('BODY','REGION','FOOTPRINT','LOCAL_SITE','SAMPLE','MODEL_DOMAIN')),representativeness TEXT NOT NULL,source_id INTEGER NOT NULL REFERENCES source(source_id),admission_status TEXT NOT NULL CHECK(admission_status IN('CANDIDATE','ADMITTED','HOLD','RETIRED')),origin TEXT NOT NULL,notes TEXT,CHECK(abundance_semantics NOT IN('RESERVE','RECOVERABLE_RESERVE')));
CREATE TABLE coverage(coverage_id INTEGER PRIMARY KEY,body_id TEXT NOT NULL REFERENCES body(body_id),domain TEXT NOT NULL,property_or_class TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('SUPPORTED','UNKNOWN','SOURCE_NOT_FOUND','SOURCE_NOT_PRESENT','SOURCE_DOES_NOT_COVER','NOT_APPLICABLE','CONFLICT')),origin TEXT NOT NULL,reason TEXT,UNIQUE(body_id,domain,property_or_class,origin));
CREATE TABLE reconciliation(reconciliation_id INTEGER PRIMARY KEY,body_id TEXT NOT NULL REFERENCES body(body_id),property_code TEXT NOT NULL,assertion_a INTEGER NOT NULL REFERENCES scientific_assertion(assertion_id),assertion_b INTEGER NOT NULL REFERENCES scientific_assertion(assertion_id),classification TEXT NOT NULL,reason TEXT,status TEXT NOT NULL);
CREATE TABLE supersession(old_assertion_id INTEGER NOT NULL REFERENCES scientific_assertion(assertion_id),new_assertion_id INTEGER NOT NULL REFERENCES scientific_assertion(assertion_id),source_id INTEGER REFERENCES source(source_id),reason TEXT NOT NULL,PRIMARY KEY(old_assertion_id,new_assertion_id));
CREATE TABLE knowledge_event(knowledge_event_id INTEGER PRIMARY KEY,event_key TEXT NOT NULL UNIQUE,event_type TEXT NOT NULL CHECK(event_type IN('OBSERVED','PUBLISHED','RELEASED','REVISED','SUPERSEDED','RETRACTED','INGESTED')),event_time TEXT NOT NULL,target_assertion_id INTEGER REFERENCES scientific_assertion(assertion_id),target_observation_id INTEGER REFERENCES observation(observation_id),target_spatial_product_id INTEGER REFERENCES spatial_product(spatial_product_id),target_source_id INTEGER REFERENCES source(source_id),CHECK((target_assertion_id IS NOT NULL)+(target_observation_id IS NOT NULL)+(target_spatial_product_id IS NOT NULL)+(target_source_id IS NOT NULL)=1));
CREATE TABLE generation_model(generation_model_id INTEGER PRIMARY KEY,model_key TEXT NOT NULL UNIQUE,name TEXT NOT NULL,version TEXT NOT NULL,status TEXT NOT NULL);
CREATE TABLE generation_policy(policy_id INTEGER PRIMARY KEY,generation_model_id INTEGER NOT NULL REFERENCES generation_model(generation_model_id),body_id TEXT NOT NULL REFERENCES body(body_id),property_code TEXT NOT NULL,policy_type TEXT NOT NULL,policy_parameters TEXT,notes TEXT,UNIQUE(generation_model_id,body_id,property_code));
CREATE TABLE world_realization(world_realization_id INTEGER PRIMARY KEY,generation_model_id INTEGER NOT NULL REFERENCES generation_model(generation_model_id),body_id TEXT NOT NULL REFERENCES body(body_id),seed TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('TEST_FIXTURE_ONLY','EXPERIMENTAL_HIDDEN_WORLD')),created_at TEXT NOT NULL);
CREATE TABLE world_constraint_binding(world_realization_id INTEGER NOT NULL REFERENCES world_realization(world_realization_id),assertion_id INTEGER NOT NULL REFERENCES scientific_assertion(assertion_id),binding_role TEXT NOT NULL,PRIMARY KEY(world_realization_id,assertion_id,binding_role));
CREATE TABLE hidden_world_state(hidden_state_id INTEGER PRIMARY KEY,world_realization_id INTEGER NOT NULL REFERENCES world_realization(world_realization_id),region_id INTEGER REFERENCES region(region_id),property_code TEXT NOT NULL,value_numeric REAL,value_text TEXT,unit TEXT,provenance TEXT NOT NULL);
CREATE TABLE project_site(project_site_id INTEGER PRIMARY KEY,world_realization_id INTEGER NOT NULL REFERENCES world_realization(world_realization_id),region_id INTEGER NOT NULL REFERENCES region(region_id),site_key TEXT NOT NULL,site_name TEXT,status TEXT NOT NULL,UNIQUE(world_realization_id,site_key));
CREATE TABLE deposit(deposit_id INTEGER PRIMARY KEY,project_site_id INTEGER NOT NULL REFERENCES project_site(project_site_id),resource_class TEXT NOT NULL,geometry_class TEXT,finite_stock_value REAL,stock_unit TEXT,concentration_value REAL,concentration_unit TEXT,depth_min REAL,depth_max REAL,depth_unit TEXT,accessibility_state TEXT,provenance TEXT NOT NULL);
CREATE TRIGGER sample_scope_guard BEFORE INSERT ON scientific_assertion WHEN NEW.scope='SAMPLE' AND NEW.sample_id IS NULL BEGIN SELECT RAISE(ABORT,'sample assertion requires sample_id'); END;
CREATE TRIGGER region_scope_guard BEFORE INSERT ON scientific_assertion WHEN NEW.scope='REGION' AND NEW.region_id IS NULL BEGIN SELECT RAISE(ABORT,'region assertion requires region_id'); END;
CREATE TRIGGER no_candidate_preferred BEFORE INSERT ON scientific_assertion WHEN NEW.preferred=1 AND NEW.admission_status<>'ADMITTED' BEGIN SELECT RAISE(ABORT,'only admitted assertions may be preferred'); END;
